use vstd::prelude::*;

verus! {

    /// determine_winner(x, y) returns
    ///   "Alice"  iff |x - y| > 1,
    ///   "Brown"  iff |x - y| ≤ 1.
    fn determine_winner(x: i8, y: i8) -> (winner: &'static str)
        requires
            // problem statement assumes both are nonnegative
            x >= 0,
            y >= 0,
        ensures
            // if the absolute difference is strictly greater than 1, we must get "Alice"
            (if x >= y { x - y } else { y - x } > 1) ==> winner == "Alice",
        ensures
            // otherwise (i.e. diff ≤ 1) we must get "Brown"
            (if x >= y { x - y } else { y - x } <= 1) ==> winner == "Brown",
    {
        // compute the signed difference
        let d = if x >= y { x - y } else { y - x };

        // return the correct string
        if d > 1 {
            "Alice"
        } else {
            "Brown"
        }
    }

}

fn main() {
    // a few informal tests; these run at runtime, but we have proved
    // the spec above for all nonnegative i8s.
    assert!(determine_winner(5, 2) == "Alice");
    assert!(determine_winner(7, 6) == "Brown");
    assert!(determine_winner(0, 0) == "Brown");
    assert!(determine_winner(1, 3) == "Alice");
}